mapper.select:
SELECT DISTINCT u.id, u.sex, u.root, u.`name`, u.tel, d.dept_name AS dept, u.email, u.`status`, ( SELECT GROUP_CONCAT( role_name SEPARATOR "，" ) FROM tb_role WHERE JSON_CONTAINS ( u.role, CONVERT ( r.id, CHAR ) ) ) AS roles FROM tb_user u JOIN tb_dept d ON u.dept_id = d.id JOIN tb_role r ON JSON_CONTAINS ( u.role, CONVERT ( r.id, CHAR ) ) WHERE 1=1
AND u.name LIKE CONCAT("%",#{name},"%")
AND u.sex=#{sex}
AND r.role_name=#{role}
AND d.id=#{deptId}
AND u.status=#{status}
LIMIT #{start},#{length}

SELECT COUNT(*)
FROM tb_user u
JOIN tb_role r ON JSON_CONTAINS ( u.role, CONVERT ( r.id, CHAR ) )
WHERE 1=1

    AND u.name LIKE "%${name}%"


    AND u.sex=#{sex}


    AND r.role_name=#{role}


    AND u.dept_id=#{deptId}


    AND u.status=#{status}

mapper.insert:
INSERT INTO tb_user SET username = #{username}, password = MD5(CONCAT(MD5(#{username}), #{password})), name = #{name}, sex = #{sex},
 tel = #{tel}, 
email=#{email}, role = #{role}, root = false, dept_id = #{deptId}, status = #{status}, create_time = #{createTime}

mapper.update:
UPDATE tb_user
username = #{username}, name = #{name}, sex = #{sex}, tel = #{tel}, email = #{email}, role = #{role}, dept_id = #{deptId},
WHERE id = #{id}

